{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investments — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbfb;--card:#fff;--muted:#6b7280;--accent:#0b7a5a;--accent-2:#0b5d87;--glass:rgba(255,255,255,0.6)}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:#0f172a;background:linear-gradient(180deg,var(--bg),#f3f7f5);}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;background:linear-gradient(90deg,rgba(11,122,90,0.06),rgba(11,93,135,0.03));backdrop-filter:blur(4px)}
    .brand{font-weight:700;letter-spacing:0.2px}
    nav a{margin-left:18px;color:var(--accent-2);text-decoration:none;font-weight:600}
    .hero{display:flex;gap:28px;padding:48px 28px;align-items:flex-start}
    .hero .left{flex:1;max-width:760px}
    h1{margin:0 0 12px;font-size:28px}
    p.lead{margin:0 0 18px;color:var(--muted)}
    .mood{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 20px}
    .mood button{background:var(--card);border:1px solid #e6eef0;padding:10px 14px;border-radius:8px;cursor:pointer}
    .mood button.active{border-color:var(--accent);box-shadow:0 6px 18px rgba(11,122,90,0.08)}
    .card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 8px 30px rgba(15,23,42,0.04);border:1px solid rgba(10,10,10,0.02)}
    .pricing-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px;margin-top:18px}
    .plan-title{font-weight:700;margin-bottom:6px}
    .price{font-size:22px;color:var(--accent);font-weight:800}
    .features{color:var(--muted);margin-top:8px}
    .cta-wrap{margin-top:16px}
    .btn{background:var(--accent);border:none;color:#fff;padding:10px 16px;border-radius:8px;cursor:pointer;font-weight:700}
    .secondary{background:#fff;border:1px solid #e1e5e9;color:var(--accent-2)}
    .side{width:360px}
    .pattern{width:100%;height:120px;background-image:url('assets/img/pattern.svg');background-size:cover;border-radius:10px}
    .goals{display:flex;flex-direction:column;gap:8px;margin-top:12px}
    .goal-check{display:flex;align-items:center;gap:10px}
    .meter{margin-top:12px}
    .path-legend{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}
    .legend-item{display:flex;align-items:center;gap:8px;color:var(--muted);font-size:13px}
    footer{padding:18px 28px;color:var(--muted);font-size:13px}
    @media(max-width:920px){.hero{flex-direction:column}.side{width:100%}.pricing-grid{grid-template-columns:1fr}}
  </style>
</head>
<body>
  <header>
    <div class="brand">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Overview</a>
      <a href="services.html">Approach</a>
      <a href="programs.html">Offerings</a>
      <a href="pricing.html">Investments</a>
      <a href="testimonials.html">Stories</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="hero">
    <div class="left">
      <div class="card">
        <h1>Pricing shaped around how you start, not just what you pay for</h1>
        <p class="lead">Choose a path matched to where you are today. Pick a mood, add the outcomes that matter, and we’ll map a clear 30-day route you can follow.</p>

        <div>
          <label style="font-weight:700">Mood-to-Method — where are you right now?</label>
          <div class="mood" role="tablist" id="moodSelector">
            <button data-key="overwhelmed" class="active">Overwhelmed</button>
            <button data-key="stuck">Stuck</button>
            <button data-key="gaining">Gaining traction</button>
            <button data-key="optimizing">Optimizing</button>
          </div>
        </div>

        <div style="display:flex;gap:14px;align-items:center;margin-top:8px">
          <div style="flex:1">
            <div style="font-size:13px;color:var(--muted)">Recommended approach</div>
            <div id="methodName" style="font-weight:800;font-size:18px;margin-top:6px">Gentle Reset</div>
            <div id="methodBlurb" style="color:var(--muted);margin-top:6px">A focused short set of practical moves to relieve pressure and make decisions easier this week.</div>
          </div>
          <div class="cta-wrap">
            <a id="primaryCta" class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>

        <div class="pricing-grid" style="margin-top:18px" id="plans">
          <div class="card">
            <div class="plan-title">Recharge Day</div>
            <div class="price">$450</div>
            <div class="features">One focused VIP-style day for practical recalibration. Ideal for clearing overwhelm and making a compact plan.</div>
            <div style="margin-top:10px"><button class="btn secondary" data-plan="recharge" onclick="choosePlan('recharge')">Select</button></div>
          </div>

          <div class="card">
            <div class="plan-title">Guided Momentum (8 weeks)</div>
            <div class="price">$1,900</div>
            <div class="features">Short weekly check-ins, a flexible habit map, and weekly action templates to build steady results.</div>
            <div style="margin-top:10px"><button class="btn secondary" data-plan="momentum" onclick="choosePlan('momentum')">Select</button></div>
          </div>

          <div class="card">
            <div class="plan-title">Signature Reset — VIP Day</div>
            <div class="price">$3,200</div>
            <div class="features">An immersive day to redesign your next 30 days with templates, priorities, and a custom micro-habit system.</div>
            <div style="margin-top:10px"><button class="btn" data-plan="vip" onclick="choosePlan('vip')">Reserve VIP Day</button></div>
          </div>
        </div>

      </div>

      <div style="margin-top:16px" class="card">
        <h3 style="margin:0 0 8px">Build your 30-day path</h3>
        <div style="color:var(--muted);font-size:14px">Select the outcomes you want and see a simple daily path that focuses effort where it matters.</div>

        <div class="goals" id="goalList">
          <label class="goal-check"><input type="checkbox" value="sleep" onchange="updatePath()" checked> Better sleep rhythms</label>
          <label class="goal-check"><input type="checkbox" value="energy" onchange="updatePath()" checked> More consistent energy</label>
          <label class="goal-check"><input type="checkbox" value="clarity" onchange="updatePath()"> Clearer focus and decisions</label>
          <label class="goal-check"><input type="checkbox" value="stress" onchange="updatePath()"> Lower day-to-day stress</label>
          <label class="goal-check"><input type="checkbox" value="movement" onchange="updatePath()"> Simple daily movement</label>
        </div>

        <div class="meter">
          <svg id="pathMap" width="100%" height="64" viewBox="0 0 600 64" preserveAspectRatio="xMidYMid meet"></svg>
          <div class="path-legend" id="legend"></div>
        </div>

      </div>

    </div>

    <aside class="side">
      <div class="card pattern" aria-hidden="true"></div>

      <div class="card" style="margin-top:12px">
        <div style="font-weight:700">Plan snapshot</div>
        <div id="planSnapshot" style="color:var(--muted);margin-top:8px">Pick a mood and goals to build a concise 30-day outline here.</div>
        <div style="margin-top:12px"><a id="secondaryCta" class="btn secondary" href="book.html">Book a time</a></div>
      </div>

      <div class="card" style="margin-top:12px">
        <div style="font-weight:700">Questions?</div>
        <div style="color:var(--muted);margin-top:8px">Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>

    </aside>

  </main>

  <footer>
    <div>© <span id="year"></span> {{BUSINESS_NAME}} — Practical frameworks for daily change · <a href="contact.html">Reach out</a></div>
  </footer>

  <script>
    (function(){
      document.getElementById('year').textContent = new Date().getFullYear();
      const moods = {
        overwhelmed:{name:'Gentle Reset',blurb:'Small, immediate moves to reduce decision load and create breathable margins.',cta:'Book a Short Reset'},
        stuck:{name:'Bridge Plan',blurb:'A 4-week bridge that focuses on one clear habit at a time to restart forward momentum.',cta:'Start a Discovery Call'},
        gaining:{name:'Momentum Coaching',blurb:'Weekly checkpoints and micro-habit scaffolds to maintain steady progress.',cta:'Claim Momentum Session'},
        optimizing:{name:'VIP Intensive',blurb:'A high-impact day to redesign your routines and priorities for the quarter.',cta:'Reserve a VIP Day'}
      };

      const moodButtons = document.querySelectorAll('#moodSelector button');
      moodButtons.forEach(b=>b.addEventListener('click', ()=>{
        moodButtons.forEach(x=>x.classList.remove('active'));
        b.classList.add('active');
        applyMood(b.getAttribute('data-key'));
      }));

      function applyMood(key){
        const m = moods[key] || moods.overwhelmed;
        document.getElementById('methodName').textContent = m.name;
        document.getElementById('methodBlurb').textContent = m.blurb;
        const primary = document.getElementById('primaryCta');
        primary.textContent = m.cta;
        primary.href = '{{PRIMARY_CTA_URL}}';
        document.getElementById('planSnapshot').textContent = m.name + ' — recommended approach updated.';
      }

      applyMood('overwhelmed');

      window.choosePlan = function(plan){
        const map = {recharge:'Recharge Day — a focused single-day reset.',momentum:'Guided Momentum — 8-week structure.',vip:'Signature Reset — VIP Day intensive.'};
        document.getElementById('planSnapshot').textContent = map[plan] || 'Plan selected.';
        document.getElementById('secondaryCta').href = 'book.html?plan='+plan;
      }

      // Path map rendering
      function updatePath(){
        const checks = Array.from(document.querySelectorAll('#goalList input')).filter(i=>i.checked).map(i=>i.value);
        const svg = document.getElementById('pathMap');
        while(svg.firstChild) svg.removeChild(svg.firstChild);
        const totalDays = 30;
        const w = 560; const h = 64; const gap = 4; const cellW = (w - (totalDays-1)*gap)/totalDays;
        svg.setAttribute('viewBox','0 0 '+w+' '+h);
        const colorMap = {sleep:'#0b7a5a',energy:'#0b5d87',clarity:'#9b5cf6',stress:'#f59e0b',movement:'#ef4444'};
        const legend = document.getElementById('legend');
        while(legend.firstChild) legend.removeChild(legend.firstChild);
        checks.forEach(g=>{
          const item = document.createElement('div'); item.className='legend-item';
          const dot = document.createElement('span'); dot.style.width='12px'; dot.style.height='12px'; dot.style.display='inline-block'; dot.style.background=colorMap[g]||'#94a3b8'; dot.style.borderRadius='3px';
          const txt = document.createElement('span'); txt.textContent = {sleep:'Sleep',energy:'Energy',clarity:'Clarity',stress:'Stress',movement:'Movement'}[g]||g;
          item.appendChild(dot); item.appendChild(txt); legend.appendChild(item);
        });

        // Strategy: distribute focus segments: first week heavy on foundation (sleep/movement), middle on energy/clarity, last week taper
        for(let d=0; d<totalDays; d++){
          const x = d*(cellW+gap);
          const rect = document.createElementNS('http://www.w3.org/2000/svg','rect');
          rect.setAttribute('x',x); rect.setAttribute('y',8); rect.setAttribute('width',cellW); rect.setAttribute('height',48); rect.setAttribute('rx',6);
          // coloring logic
          let shade = '#e6eef0';
          if(checks.length === 0) shade = '#e6eef0';
          else{
            const pick = checks[(Math.floor(d/7)+d) % checks.length]; // deterministic mix
            shade = colorMap[pick] || '#cbd5e1';
          }
          rect.setAttribute('fill',shade);
          svg.appendChild(rect);
        }

        // snapshot text
        const summary = checks.length ? checks.map(k=>({sleep:'better sleep',energy:'steady energy',clarity:'clear focus',stress:'calmer days',movement:'consistent movement'}[k])).filter(Boolean).slice(0,3).join(', ') : 'no outcomes selected';
        document.getElementById('planSnapshot').textContent = '30-day outline focused on: ' + summary + '.';
      }

      window.updatePath = updatePath;
      updatePath();

    })();
  </script>
</body>
</html>"} 
{"path":"testimonials.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Stories — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--muted:#6b7280;--accent:#0b7a5a}
    body{margin:0;font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Arial;color:#07101a;background:linear-gradient(180deg,#fcfffd,#f7fbfa)}
    header{display:flex;align-items:center;justify-content:space-between;padding:16px 26px;background:#fff;border-bottom:1px solid #eef2f3}
    nav a{margin-left:18px;color:var(--accent);text-decoration:none;font-weight:600}
    .wrap{max-width:1100px;margin:28px auto;padding:0 18px}
    h1{margin:0 0 8px}
    p.lead{color:var(--muted);margin-top:0}
    .filters{display:flex;gap:8px;flex-wrap:wrap;margin:18px 0}
    .filter{background:#fff;border:1px solid #e8f0ee;padding:8px 12px;border-radius:8px;cursor:pointer}
    .grid{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
    .testi{background:#fff;border-radius:12px;padding:16px;box-shadow:0 6px 20px rgba(11,122,90,0.05);border:1px solid rgba(10,10,10,0.03)}
    .quote{color:#102329;font-style:normal}
    .meta{color:var(--muted);font-size:14px;margin-top:10px}
    .mood-line{display:flex;gap:8px;margin-top:12px}
    .small{font-size:13px;color:var(--muted)}
    .path-mini{height:48px;margin-top:12px;background-image:url('assets/img/pattern.svg');background-size:cover;border-radius:8px}
    @media(max-width:900px){.grid{grid-template-columns:1fr}nav{display:none}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Overview</a>
      <a href="services.html">Approach</a>
      <a href="programs.html">Offerings</a>
      <a href="pricing.html">Investments</a>
      <a href="testimonials.html">Stories</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <h1>Stories from people who used a clear path</h1>
    <p class="lead">Real feedback that focuses on outcomes and practical habit changes — no overpromises, just steady results.</p>

    <div class="filters">
      <div class="filter" data-filter="all" onclick="applyFilter('all')">All</div>
      <div class="filter" data-filter="sleep" onclick="applyFilter('sleep')">Sleep</div>
      <div class="filter" data-filter="energy" onclick="applyFilter('energy')">Energy</div>
      <div class="filter" data-filter="clarity" onclick="applyFilter('clarity')">Clarity</div>
      <div class="filter" data-filter="stress" onclick="applyFilter('stress')">Calmer days</div>
      <div class="filter" data-filter="vip" onclick="applyFilter('vip')">VIP Day</div>
    </div>

    <div class="grid" id="testimonialsGrid">
      <!-- cards injected -->
    </div>

    <div style="margin-top:22px" class="card" id="interactiveCard">
      <div class="testi">
        <div style="font-weight:700">Compare paths</div>
        <div class="small" style="margin-top:6px">Pick outcomes to see which stories align with the plan you need.</div>
        <div style="margin-top:10px">
          <label><input type="checkbox" value="sleep" onchange="syncFilter()"> Sleep</label>
          <label style="margin-left:8px"><input type="checkbox" value="energy" onchange="syncFilter()"> Energy</label>
          <label style="margin-left:8px"><input type="checkbox" value="clarity" onchange="syncFilter()"> Clarity</label>
        </div>
        <div id="miniPath" class="path-mini"></div>
      </div>
    </div>

  </main>

  <script>
    (function(){
      const testimonials = [
        {name:'A. R.',tag:'sleep',role:'Parent, full schedule',text:'We adjusted 3 small cues and sleep improved. The days feel less reactive.'},
        {name:'M. S.',tag:'energy',role:'Founder',text:'Weekly micro-actions kept me from crashing and I had steadier afternoons.'},
        {name:'T. L.',tag:'clarity',role:'Designer',text:'Short rituals before work gave me a predictable focus window.'},
        {name:'C. J.',tag:'vip',role:'Executive',text:'The intensive day reoriented my priorities; the next 30 days were far easier to hold.'},
        {name:'P. K.',tag:'stress',role:'Teacher',text:'A simple, tailored 4-week scaffold reduced daily friction and reactivity.'},
      ];

      const grid = document.getElementById('testimonialsGrid');
      function renderList(list){
        grid.innerHTML = '';
        list.forEach(t=>{
          const card = document.createElement('div'); card.className='testi';
          card.innerHTML = '<div class="quote">"'+t.text+'"</div><div class="meta">— '+t.name+' · '+t.role+'</div>';
          const moodline = document.createElement('div'); moodline.className='mood-line';
          const tag = document.createElement('div'); tag.className='small'; tag.textContent = 'Focus: '+t.tag; moodline.appendChild(tag);
          card.appendChild(moodline);
          grid.appendChild(card);
        });
      }

      renderList(testimonials);

      window.applyFilter = function(f){
        if(f==='all') return renderList(testimonials);
        renderList(testimonials.filter(t=>t.tag===f));
      }

      window.syncFilter = function(){
        const checked = Array.from(document.querySelectorAll('#interactiveCard input[type=checkbox]')).filter(i=>i.checked).map(i=>i.value);
        // simple highlight: reorder testimonials that match
        const primary = testimonials.filter(t=>checked.includes(t.tag));
        const secondary = testimonials.filter(t=>!checked.includes(t.tag));
        renderList(primary.concat(secondary));
        // render mini path: color blocks generated inline
        const mini = document.getElementById('miniPath');
        mini.innerHTML = '';
        const colors = {sleep:'#0b7a5a',energy:'#0b5d87',clarity:'#9b5cf6'};
        if(checked.length===0){ mini.style.background='linear-gradient(90deg,#f3f7f5,#eef6f1)'; return }
        const frag = document.createElement('div'); frag.style.display='flex'; frag.style.height='48px';
        for(let i=0;i<24;i++){ const s = document.createElement('div'); s.style.flex='1'; s.style.marginRight=(i<23?'2px':'0'); s.style.background=colors[checked[i % checked.length]]; frag.appendChild(s) }
        mini.innerHTML=''; mini.appendChild(frag);
      }

    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--accent:#0b7a5a;--muted:#56707a}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;background:#fbfdfc;color:#082022}
    header{display:flex;align-items:center;justify-content:space-between;padding:16px 24px}
    nav a{margin-left:16px;color:var(--accent);text-decoration:none}
    .wrap{max-width:900px;margin:30px auto;padding:0 18px}
    .card{background:#fff;padding:18px;border-radius:12px;box-shadow:0 8px 40px rgba(11,122,90,0.04)}
    h1{margin:0 0 6px}
    .form-row{display:flex;gap:12px;margin-top:12px}
    input,select,textarea{padding:10px;border-radius:8px;border:1px solid #e6eef0;font-size:15px;width:100%}
    .small{color:var(--muted);font-size:14px}
    .btn{background:var(--accent);color:#fff;padding:10px 14px;border-radius:8px;border:none;cursor:pointer;font-weight:700}
    .inline{display:inline-block}
    .summary{margin-top:12px;color:var(--muted)}
    .path-preview{margin-top:12px;border-radius:8px;height:64px;background-image:url('assets/img/pattern.svg');background-size:cover}
    @media(max-width:720px){.form-row{flex-direction:column}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Overview</a>
      <a href="services.html">Approach</a>
      <a href="programs.html">Offerings</a>
      <a href="pricing.html">Investments</a>
      <a href="testimonials.html">Stories</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main class="wrap">
    <div class="card">
      <h1>Reserve a planning session</h1>
      <p class="small">Start with a short call or book a VIP session. Use the Mood-to-Method control to tailor the recommended format.</p>

      <div style="margin-top:12px">
        <label style="font-weight:700">Mood-to-Method</label>
        <div style="display:flex;gap:8px;margin-top:8px" id="moodBits">
          <button data-key="overwhelmed" class="inline active" onclick="setMood('overwhelmed')">Overwhelmed</button>
          <button data-key="stuck" class="inline" onclick="setMood('stuck')">Stuck</button>
          <button data-key="gaining" class="inline" onclick="setMood('gaining')">Gaining</button>
          <button data-key="optimizing" class="inline" onclick="setMood('optimizing')">Optimizing</button>
        </div>
      </div>

      <form id="bookForm" onsubmit="submitBooking(event)">
        <div class="form-row">
          <div style="flex:2">
            <label class="small">Your name</label>
            <input id="name" required>
          </div>
          <div style="flex:1">
            <label class="small">Phone</label>
            <input id="phone" placeholder="{{PHONE}}">
          </div>
        </div>

        <div class="form-row" style="margin-top:12px">
          <div style="flex:1">
            <label class="small">Email</label>
            <input id="email" type="email" placeholder="{{EMAIL}}">
          </div>
          <div style="flex:1">
            <label class="small">Session type</label>
            <select id="sessionType">
              <option value="call">30-min Discovery Call</option>
              <option value="recharge">Recharge Day</option>
              <option value="vip">VIP Day Intensive</option>
            </select>
          </div>
        </div>

        <div style="margin-top:12px">
          <label class="small">Choose goals (for a tailored 30-day plan)</label>
          <div style="margin-top:8px">
            <label><input type="checkbox" value="sleep" onchange="updatePreview()"> Sleep</label>
            <label style="margin-left:8px"><input type="checkbox" value="energy" onchange="updatePreview()"> Energy</label>
            <label style="margin-left:8px"><input type="checkbox" value="clarity" onchange="updatePreview()"> Clarity</label>
            <label style="margin-left:8px"><input type="checkbox" value="movement" onchange="updatePreview()"> Movement</label>
          </div>
        </div>

        <div class="summary" id="sessionSummary">Recommended: Short discovery call focused on immediate, practical next steps.</div>

        <div class="path-preview" id="previewPath"></div>

        <div style="margin-top:12px;display:flex;gap:12px;align-items:center">
          <button type="submit" class="btn" id="bookBtn">{{PRIMARY_CTA_LABEL}}</button>
          <div class="small">Or call <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
        </div>
      </form>

    </div>
  </main>

  <script>
    (function(){
      const moods = {
        overwhelmed:{session:'call',label:'Short Reset call — 30 minutes',cta:'Start a Reset Call'},
        stuck:{session:'recharge',label:'Recharge Day — focused single-day work',cta:'Reserve Recharge Day'},
        gaining:{session:'call',label:'Momentum Session — 45 minutes review',cta:'Book Momentum Session'},
        optimizing:{session:'vip',label:'VIP Day — in-depth redesign',cta:'Reserve VIP Day'}
      };

      function setMood(key){
        document.querySelectorAll('#moodBits button').forEach(b=>b.classList.remove('active'));
